  ('3', 'Side street off the Glen Road', 'Gransha Grill', null, null, 'Evenings & weekends fine', 'Quiet residential street off the Glen Road — Gransha Drive or Gransha Grove side. No wardens ever spotted. Walk right back to the Grill.', 54.5827, -5.9869, null, 8, 'public', 'published', null, array['gransha grill','glen road','gransha drive','gransha grove','turf lodge','gransha park']::text[], '2 min', 0.07, 'ParkingPro_BT', 29, null, 'belfast', false),
  ('5', 'Hannahstown Hill roadside verge', 'Black Mountain', null, null, 'No restrictions', 'Wide verge fits 6+ easily. Better than the main area on busy days — most tourists miss it.', 54.6175, -6.019, null, 7, 'public', 'published', null, array['black mountain','black mountain walk','hannahstown']::text[], '~5 min', 0.25, 'DogWalkerDermot', 52, null, 'belfast', true),
  ('9', 'Falls Road — just before the Broadway lights', 'Broadway / Falls Road', null, null, 'Free — but get there early', 'Local knowledge: coming down towards the lights where you turn left into Broadway, the stretch right at the junction is double yellows — but just before them the lines stop and you can park free on the street. Only room for about 3 cars each side, so it is gone if you are not early.', 54.5888, -5.9605, null, 6, 'public', 'published', null, array['broadway','broadway lights','falls road','west belfast','westlink','rise sculpture','the globes','free parking','on-street','beechmount']::text[], 'On the road', 0, 'ParkEasy', 0, null, 'belfast', false),
  ('11', 'International Wall lay-by', 'Falls Road', null, null, 'Free, no restrictions', 'Handy for quick visits beside the murals. Hidden gem — rarely full even on tourist days.', 54.5975, -5.9695, null, 6, 'public', 'published', null, array['falls road','murals','international wall']::text[], '~3 min', 0.09, 'DivisDweller', 33, null, 'belfast', false),
  ('13', 'Innisfayle Park overflow', 'Cave Hill', null, null, 'Residential — be respectful', 'When the castle car park is rammed, locals use this quiet road. Always space. Short walk up.', 54.635, -5.958, null, null, 'public', 'published', null, array['cave hill','innisfayle','antrim road']::text[], '~7 min', 0.19, 'AntrimRoadAndy', 51, null, 'belfast', true),
  ('24', 'Waring Street hidden lay-by', 'Cathedral Quarter', null, null, 'Evenings & weekends free', 'Small lay-by most people miss — tucked just off Waring Street. Cathedral Quarter regulars swear by it.', 54.601, -5.9275, null, 4, 'public', 'published', null, array['cathedral quarter','waring street','custom house square']::text[], '3 min', 0.08, 'CQ_Insider', 38, null, 'belfast', false),
  ('27', 'Botanic Avenue side streets', 'Botanic Gardens', null, null, 'Evenings & weekends free', 'Quiet residential streets off Botanic Avenue. Locals park here instead of paying nearby car parks.', 54.5835, -5.9345, null, null, 'public', 'published', null, array['botanic gardens','botanic avenue','botanic','queens university']::text[], '4 min', 0.15, 'BotanicLocal', 44, null, 'belfast', false),
  ('30', 'May Street on-street', 'St George''s Market', null, null, 'Free Sunday mornings', 'Great for Sunday market visits — usually spaces even on busy market days. 3 min flat walk to the entrance.', 54.5945, -5.923, null, null, 'public', 'published', null, array['st george''s market','may street','george''s market','markets']::text[], '3 min', 0.12, 'SundayMarket', 29, null, 'belfast', false),
  ('36', 'Ormeau Embankment riverside', 'Ormeau Road', null, null, 'Free all day', 'Completely free riverside parking off Ormeau Embankment. Walk along the Lagan towpath to the Gasworks or city centre. Locals keep this quiet!', 54.5882, -5.9185, null, null, 'public', 'published', null, array['ormeau embankment','lagan','riverside','ormeau','south belfast','free parking']::text[], '5 min', 0.2, 'LagansideLad', 67, true, 'belfast', true),
  ('46', 'Hamilton Dock overflow', 'Titanic Quarter', null, null, 'Free all day', 'Overflow area near Hamilton Dock — free and often has spaces when Queens Road fills up on peak days. Easy walk to Titanic Belfast and SS Nomadic.', 54.6068, -5.9152, null, null, 'public', 'published', null, array['titanic quarter','hamilton dock','ss nomadic','titanic belfast','titanic']::text[], '5 min', 0.2, 'TitanicLocal', 43, null, 'belfast', false),
  ('54', 'Lagan Towpath riverside (free)', 'Lagan Towpath', null, null, 'Free all day', 'Completely free parking along the Lagan towpath riverside roads. Walk or cycle along the Lagan from here. Popular with locals but rarely on parking apps.', 54.581, -5.9155, null, null, 'public', 'published', null, array['lagan towpath','riverside','lagan','south belfast','free parking']::text[], 'Riverside start', 0, 'LaganLocal', 58, false, 'belfast', true),
  ('58', 'Lagan Meadows', 'Lagan Meadows', null, null, 'Free all day', 'Rolling riverside meadows south of the city, hugging the River Lagan. Few amenities — just wild, quiet walking and wildlife. Locals love it. Connect onto the towpath towards Shaws Bridge.', 54.565, -5.923, null, 30, 'public', 'published', null, array['lagan meadows','south belfast','walks','lagan','riverside','free parking','dog walk']::text[], 'Trail start', 0, 'MeadowsWalker', 38, null, 'belfast', false),
  ('60', 'Minnowburn car park', 'Minnowburn', null, null, 'Free all day', 'Green oasis in the Lagan Valley Regional Park. Free car park, then trails along the Lagan and through woodland and farmland. Chainsaw sculptures, a wildlife pond, and Terrace Hill views over the valley. Walk to the Giant''s Ring nearby.', 54.536, -5.941, null, 40, 'public', 'published', null, array['minnowburn','lagan valley','south belfast','walks','national trust','free parking','terrace hill','dog walk']::text[], 'Trail start', 0, 'MinnowburnLocal', 47, null, 'belfast', true),
  ('66', 'LORAG centre / Shaftesbury Rec kerbside', 'Lower Ormeau / Gasworks', null, null, 'Free all day', 'Founder pick: free kerbside and community-centre parking around LORAG on the Lower Ormeau, beside the Gasworks. Park up and walk into the city centre in minutes — ideal on match and gig days.', 54.59, -5.9235, null, null, 'public', 'published', null, array['lorag','shaftesbury','lower ormeau','gasworks','south belfast','free parking','city centre walk']::text[], '8 min', 0.3, 'ParkEasy', 0, true, 'belfast', false),
  ('70', 'Giant''s Ring car park', 'Giant''s Ring / Ballynahatty', null, null, 'Free — open year round', 'Small free car park at the Giant''s Ring off Ballynahatty Road, near Shaw''s Bridge. A 5,000-year-old henge with a huge open field, and almost nobody knows the car park is there. Free all year. Trails link down to the Lagan and round to Minnowburn — the red-arrow loop is about an hour.', 54.5406, -5.948, null, 15, 'public', 'published', null, array['giants ring','giant''s ring','ballynahatty','ballylesson','shaws bridge','drumbo','free parking','walks','dog walk','south belfast','henge']::text[], 'Right there', 0, 'ParkEasy', 0, null, 'belfast', false),
  ('72', 'Lisnabreeny Road car park (National Trust)', 'Cregagh Glen / Lisnabreeny', null, null, 'Free — limited spaces', 'The National Trust''s small free car park on Lisnabreeny Road — the proper way into Cregagh Glen and up to the views over the city. Only a handful of spaces, so if it''s full come back another time: there is NO parking on Manse Road or at the Cregagh Glen entrance on the A55. Alternative is the side streets at the top of Cregagh Road before it meets the A55.', 54.554, -5.885, null, 10, 'public', 'published', null, array['cregagh glen','lisnabreeny','national trust','castlereagh','cregagh','free parking','walks','dog walk','east belfast','views']::text[], 'Trail start', 0, 'ParkEasy', 0, null, 'belfast', false),
  ('76', 'Riddel Hall (Queen''s) car park', 'Stranmillis / Malone Road', null, null, 'Free — subject to availability', 'Queen''s free car park at Riddel Hall on the Stranmillis Road — free at all times, subject to space. A rare free option this far up the Malone/Stranmillis end, where nearly everything else is permit or pay. Queen''s main site also opens up for parking evenings and weekends, and on-street around the university is usually free before 8am and after 6pm.', 54.5722, -5.9395, null, 40, 'public', 'published', null, array['riddel hall','queens university','qub','stranmillis','malone road','south belfast','free parking','university']::text[], 'Right there', 0, 'ParkEasy', 0, null, 'belfast', false),
  ('77', 'Musgrave Park car park', 'Musgrave Park / Stockman''s Lane', null, null, 'Free — park hours', 'Free car park at Musgrave Park off Stockman''s Lane, around 22 spaces. Worth knowing because most listings online tell you there is no parking inside the park and to leave the car on the surrounding streets — there is a car park, it is just small, so it fills on match and dog-walking mornings. Confirmed in person.', 54.5665, -5.964, null, 22, 'public', 'published', null, array['musgrave park','musgrave','stockmans lane','stockman''s lane','balmoral','south belfast','free parking','park','dog walk','playing fields','rugby']::text[], 'Right there', 0, 'ParkEasy', 0, null, 'belfast', false),
  ('204', 'Wallace Park', 'Wallace Park', null, null, 'Free — park hours', 'Free parking at Wallace Park — Victorian park with walks, sports pitches and a duck pond. Great for families and dog walkers.', 54.518, -6.036, null, null, 'public', 'published', null, array['lisburn','wallace park','walks','free parking','dog walk']::text[], 'Trail start', 0, 'LisburnLocal', 0, false, 'lisburn', false),
  ('300', 'Lower Ormeau — small free spot off the Embankment', 'Lower Ormeau / Gasworks', null, null, 'Free — fills up from the morning rush', 'Community pick from Ciaran M: a handy free spot for getting into the city centre, with room for about six to eight cars. It generally fills from rush hour in the morning, so it is a better bet later in the day or in the evening. Tight enough that a smaller car helps — worth knowing before you commit to the turn.', 54.590009, -5.921546, null, 8, 'public', 'published', null, array['lower ormeau','gasworks','ormeau embankment','south belfast','free parking','city centre walk','commuter']::text[], '12 min', 0.57, 'Ciaran M · ParkEasy community', 1, true, 'belfast', false),
  ('304', 'Marine Gardens / Seacliff Rd', 'Ballyholme', null, null, 'Free — no restrictions', 'Free on-street parking along Seacliff Rd towards Ballyholme. Lovely bay views and an easy coastal walk.', 54.66, -5.662, null, null, 'public', 'published', null, array['bangor','marine gardens','seacliff road','ballyholme','seafront','free parking']::text[], 'On the road', 0, 'BangorLocal', 0, true, 'bangor', false),
  ('402', 'Valley Leisure Centre', 'Valley Park', null, null, 'Free — park hours', 'Free parking at Valley Leisure Centre and the Valley Park — walking trails, playing fields and the leisure centre. ESB rapid + AC EV chargers on site (community estimate).', 54.676, -5.93, null, null, 'public', 'published', null, array['newtownabbey','valley park','valley leisure centre','walks','free parking','dog walk']::text[], 'Trail start', 0, 'NewtownabbeyLocal', 0, false, 'newtownabbey', false),
  ('504', 'Queen''s Quay Car Park', 'Guildhall / River Foyle', null, null, 'Free all day', 'Free 37-space car park beside the River Foyle, short stroll from the Guildhall and Peace Bridge. Tucked away so it rarely fills — locals keep this one quiet.', 54.9978, -7.3068, null, 37, 'public', 'published', null, array['derry','queens quay','guildhall','waterfront','river foyle']::text[], '~5 min', 0, 'Derry Local', 0, true, 'derry', false),
  ('505', 'Foyle Road Car Park', 'Craigavon Bridge / Foyle Valley Railway Museum', null, null, 'Free all day', 'Free 89-space surface car park off Foyle Road near the Railway Museum. 6-min walk to the city centre and usually has spaces when everything else is full.', 54.995, -7.309, null, 89, 'public', 'published', null, array['derry','foyle road','craigavon bridge','railway museum']::text[], '~6 min', 0, 'Derry Local', 0, true, 'derry', false),
  ('536', 'Canal Bank Car Park', 'Newry Canal / Newry Rowing Club', null, null, 'Free all day', 'Quiet free car park along the banks of the historic Newry Canal — very few visitors know about it. Walk along the towpath straight into the city centre.', 54.1735, -6.3412, null, 13, 'public', 'published', null, array['newry','canal bank','canal','free parking']::text[], '~6 min', 0, 'Newry Local', 0, true, 'newry', false),
  ('540', 'Railway Avenue Free Parking', 'Newry Train Station / Dublin Road', null, null, 'Free all day', 'Quiet residential street near Newry train station with free all-day parking — ideal for commuters or anyone heading into town on foot. Very few tourists know to park here.', 54.1794, -6.3377, null, null, 'public', 'published', null, array['newry','railway avenue','train station','free parking']::text[], '~7 min', 0, 'Newry Local', 0, true, 'newry', false),
  ('567', 'Steeple Road On-Street', 'Antrim Round Tower', null, null, 'Free all day', 'Quiet residential on-street parking along Steeple Road, short walk from the famous Antrim Round Tower. Virtually unknown to visitors. Completely free with no restrictions.', 54.7258, -6.2082, null, 20, 'public', 'published', null, array['antrim','steeple road','round tower','free','hidden gem']::text[], '~2 min', 0, 'Antrim Local', 0, true, 'antrim', false),
  ('568', 'Tesco Extra Car Park, Castle Way', 'Tesco Extra / Castle Mall', null, null, 'Free, customers only', 'The large Tesco Extra car park on Castle Way has overflow capacity locals use for a quick town centre visit. Far less busy than the Central Car Park on weekends.', 54.7205, -6.2115, null, 300, 'private', 'published', 'Marty Rooney, 19 Aug 2026 — knows these car parks, live for months', array['antrim','tesco','castle way','supermarket','free','hidden gem']::text[], '~4 min', 0, 'Antrim Local', 0, false, 'antrim', false),
  ('608', 'Park Street Quiet Free Layby', 'Mount Street Car Park / Town Centre', null, null, 'Free all day', 'Quiet stretch of free on-street parking on Park Street alongside the Mount Street area — often overlooked by visitors who head straight to the paid multi-storey.', 54.8622, -6.2805, null, 15, 'public', 'published', null, array['ballymena','park street','mount street','free parking','hidden gem','quiet']::text[], '~6 min', 0, 'Ballymena Local', 0, true, 'ballymena', false),
  ('609', 'Circular Road East Free Car Park', 'East Ballymena / Braid area', null, null, 'Free all day', 'Council car park on Circular Road East — charges dropped in 2024 and remains largely unknown to casual visitors. Short walk into town from the east side.', 54.8651, -6.267, null, 50, 'public', 'published', null, array['ballymena','circular road','braid','east ballymena','free parking','hidden gem']::text[], '~8 min', 0, 'Ballymena Local', 0, true, 'ballymena', false),
  ('637', 'Waterside Car Park (Castle Place)', 'River Bann footbridge / Coleraine town centre', null, null, 'Free, arrive by 9am on weekdays', 'Free car park on the Waterside at Castle Place beside the River Bann. Cross the footbridge to reach the town centre in about 7 minutes. Popular with locals who arrive early.', 55.1295, -6.669, null, null, 'public', 'published', null, array['coleraine','waterside','castle place','river bann','free parking','hidden gem']::text[], '~7 min', 0, 'Coleraine Local', 0, true, 'coleraine', false),
  ('639', 'Beresford Avenue On-Street', 'Coleraine town centre / Coleraine Museum', null, null, 'Free all day', 'Lesser-known free on-street option on Beresford Avenue, short walk from the town centre and handy for Coleraine Museum. Locals use it to avoid town centre charges entirely.', 55.131, -6.672, null, null, 'public', 'published', null, array['coleraine','beresford avenue','on-street','free','hidden gem','museum']::text[], '~6 min', 0, 'Coleraine Local', 0, true, 'coleraine', false),
  ('668', 'Ramore Avenue Residential Lay-bys', 'Ramore Head', null, null, 'Free, no time restrictions', 'Free unrestricted lay-by spaces along Ramore Avenue on the peninsula approach to Ramore Head. Visitors queue for the Harbour lot — locals park here and walk down in minutes. Stunning views of both bays.', 55.2098, -6.6658, null, null, 'public', 'published', null, array['portrush','ramore avenue','ramore head','free parking','hidden gem']::text[], '~3 min', 0, 'Portrush Local', 0, true, 'portrush', false),
  ('669', 'Mark Street Residential On-Street', 'Portrush Town Centre & West Strand', null, null, 'Free, no time restrictions', 'Quiet residential on-street parking on Mark Street — one of three parallel streets most tourists ignore. Five-minute flat walk to both the harbour and West Strand Beach. Completely free all day.', 55.2078, -6.6698, null, null, 'public', 'published', null, array['portrush','mark street','residential','free parking','hidden gem','west strand']::text[], '~5 min', 0, 'Portrush Local', 0, true, 'portrush', false),
  ('699', 'Scotch Quarter Side Streets', 'Scotch Quarter / Carrickfergus', null, null, 'Free evenings & Sundays, 1 hr daytime', 'Residential side streets off Scotch Quarter near the old town offer free parking in the evenings and Sundays. Locals use these to avoid castle car park crowds during summer events.', 54.7162, -5.8055, null, null, 'public', 'published', null, array['carrickfergus','scotch quarter','on-street','hidden gem','free','evening parking']::text[], '~4 min', 0, 'Carrickfergus Local', 0, true, 'carrickfergus', false),
  ('700', 'Windrose / Rodgers Quay Overflow', 'Carrickfergus Marina / The Windrose Restaurant', null, null, 'Free, no restrictions observed', 'Small informal parking area at Rodgers Quay near the marina and The Windrose restaurant. Rarely full outside major events with great harbour views.', 54.714, -5.8062, null, 25, 'public', 'published', null, array['carrickfergus','marina','windrose','rodgers quay','harbour','hidden gem']::text[], '~2 min', 0, 'Carrickfergus Local', 0, null, 'carrickfergus', false),
  ('728', 'Victoria Road On-Street (The Roddens end)', 'Larne Museum & Arts Centre', null, null, 'Free all day', 'Free unrestricted on-street parking along Victoria Road near The Roddens. Confirmed by the council as an alternative to the Fairhill Pay & Display. Most visitors pay at Fairhill instead.', 54.8555, -5.821, null, null, 'public', 'published', null, array['larne','victoria road','the roddens','free on-street','museum','hidden gem']::text[], '~5 min', 0, 'Larne Local', 0, true, 'larne', false),
  ('729', 'Riverdale Car Park', 'Larne Town Centre (west side)', null, null, 'Free all day', 'Lesser-known free council car park on the western fringe of Larne town centre. Locals use it to avoid the paid car parks — a genuine free alternative just a short walk from Main Street.', 54.851, -5.824, null, 55, 'public', 'published', null, array['larne','riverdale','free parking','town centre','hidden gem']::text[], '4 min', 0, 'Larne Local', 0, true, 'larne', false),
  ('759', 'Hollyhill Link Road Car Park', 'Forthill Park / Enniskillen town centre', null, null, 'Free all day', 'A genuine local secret — free car park off Hollyhill Link Road on the edge of Forthill Park. Described locally as ''one of the few free facilities close to town''. Most visitors never find it.', 54.3478, -7.641, null, 40, 'public', 'published', null, array['enniskillen','hollyhill','forthill','free parking','hidden gem']::text[], '~7 min', 0, 'Enniskillen Local', 0, true, 'enniskillen', false),
  ('760', 'Wellington Road Overflow Lay-By', 'Fermanagh House / Enniskillen town centre', null, null, 'Free, no marked restrictions', 'Little-known line of free lay-by parking spaces on Wellington Road near Fermanagh House. No ticket needed, unmetered, short walk from the High Street. Goes quickly on market days.', 54.3461, -7.6415, null, 15, 'public', 'published', null, array['enniskillen','wellington road','free parking','hidden gem','lay-by']::text[], '~5 min', 0, 'Enniskillen Local', 0, true, 'enniskillen', false),
  ('789', 'Omagh Riverside Walk Lay-By', 'River Strule / Omagh Riverside Walk', null, null, 'Free all day, no restrictions', 'Quiet lay-by alongside the River Strule used by locals visiting the Riverside Walk. Virtually unknown to visitors and completely free — walk straight onto the riverside path.', 54.594, -7.294, null, null, 'public', 'published', null, array['omagh','riverside','river strule','hidden gem','free','abbey bridge']::text[], 'Right there', 0, 'Omagh Local', 0, false, 'omagh', false),
  ('790', 'Campsie Road Quiet Street Parking', 'Campsie Road / west Omagh', null, null, 'Free all day', 'Residential street on the western edge of the town centre where locals park for free and walk in. Zero charge, zero hassle, ~8 minutes on foot to the High Street.', 54.5985, -7.3055, null, null, 'public', 'published', null, array['omagh','campsie road','free','hidden gem','residential']::text[], '~8 min', 0, 'Omagh Local', 0, true, 'omagh', false),
  ('817', 'Shamble Lane On-Street', 'Dungannon town centre / Scotch Street', null, null, 'Free, no restrictions', 'Tucked just off Scotch Street, Shamble Lane is a quiet back street most visitors overlook entirely. Locals use it when main car parks are full — especially handy on market day Thursdays.', 54.5031, -6.7712, null, null, 'public', 'published', null, array['dungannon','shamble lane','on-street','free','hidden gem']::text[], '~3 min', 0, 'Dungannon Local', 0, true, 'dungannon', false),
  ('820', 'Hill of the O''Neill Car Park', 'Hill of the O''Neill / Castle Hill heritage site', null, null, 'Free all day', 'A little-known free parking area at the base of Castle Hill, beside the Hill of the O''Neill heritage site. Almost always quiet — short downhill walk to the town centre.', 54.505, -6.766, null, null, 'public', 'published', null, array['dungannon','hill of the oneill','castle hill','heritage','free','hidden gem']::text[], '~5 min', 0, 'Dungannon Local', 0, true, 'dungannon', false),
  ('848', 'Loy Street Side Streets', 'Cookstown Main Street (Loy Street)', null, null, 'Free all day', 'Network of side streets feeding off Loy Street offers free unmarked parking most visitors drive straight past. Locals know these quiet residential pockets as the best free option near everything on the Main Street.', 54.6455, -6.746, null, 12, 'public', 'published', null, array['cookstown','loy street','main street','hidden gem','side street','free']::text[], '~3 min', 0, 'Cookstown Local', 0, true, 'cookstown', false),
  ('849', 'Chapel Street Quiet Bays', 'Holy Trinity Catholic Church / Cookstown', null, null, 'Free all day; busier Sunday mornings', 'A stretch of underused on-street bays on Chapel Street near Holy Trinity Church — right in the heart of the Main Street but overlooked by most. Completely free, zero hassle.', 54.6441, -6.7447, null, 10, 'public', 'published', null, array['cookstown','chapel street','church street','hidden gem','free parking','main street']::text[], '~2 min', 0, 'Cookstown Local', 0, true, 'cookstown', false),
  ('869', 'Dock Street Riverside Layby', 'Canal Basin / River Mourne Towpath', null, null, 'Free all day', 'Informal layby on Dock Street alongside the River Mourne towpath — almost entirely unknown to visitors. Perfect for reaching the Canal Basin and riverside walks.', 54.8248, -7.4592, null, 15, 'public', 'published', null, array['strabane','dock street','canal basin','river mourne','towpath','hidden gem','free']::text[], '~6 min', 0, 'Strabane Local', 0, false, 'strabane', false),
  ('870', 'Strabane Retail Park Overflow', 'Strabane Retail Park / Upper Main Street', null, null, 'Free all day', 'Outer overflow section of Strabane Retail Park — largely unmarked and almost always empty. Short walk from the upper town centre. Only locals in the know use this area.', 54.829, -7.4668, null, 20, 'private', 'published', 'Marty Rooney, 19 Aug 2026 — knows these car parks, live for months', array['strabane','retail park','overflow','upper main street','hidden gem','free']::text[], '~5 min', 0, 'Strabane Local', 0, false, 'strabane', false),
  ('889', 'The Mall / Cathedral Hill Lay-by', 'Down Cathedral / St Patrick''s Grave', null, null, 'Free all day', 'Small informal lay-by at the top of the Mall on Cathedral Hill. Puts you right at the entrance to St Patrick''s Grave without any charge. Often missed by visitors who head to the paid Market Street car park.', 54.325, -5.7143, null, null, 'public', 'published', null, array['downpatrick','the mall','cathedral hill','down cathedral','st patricks grave','hidden gem','free']::text[], 'Right there', 0, 'Downpatrick Local', 0, true, 'downpatrick', false),
